package com.hms.reports;
import com.hms.appointments.*; import com.hms.audit.*; import com.hms.queue.*; import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/reports") public class ReportingController {private final TenantRepository tenants;private final AppointmentRepository appointments;private final QueueTokenRepository tokens;private final AuditLogRepository audit;public ReportingController(TenantRepository t,AppointmentRepository a,QueueTokenRepository q,AuditLogRepository l){tenants=t;appointments=a;tokens=q;audit=l;} @GetMapping("/appointments") public AppointmentSummaryDto appointments(@PathVariable String tenantSlug){UUID id=tenant(tenantSlug);List<Appointment> rows=appointments.findAllByTenantIdOrderByStartsAtAsc(id);Map<String,Long> counts=new TreeMap<>();rows.forEach(a->counts.merge(a.getStatus().name(),1L,Long::sum));return new AppointmentSummaryDto(rows.size(),counts);} @GetMapping("/queue") public Map<String,Long> queue(@PathVariable String tenantSlug){return tokens.findAllByTenantId(tenant(tenantSlug)).stream().collect(java.util.stream.Collectors.groupingBy(x->x.getStatus().name(),TreeMap::new,java.util.stream.Collectors.counting()));} @GetMapping("/audit") public List<AuditLog> audit(@PathVariable String tenantSlug){return audit.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug));} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
